// Builds src/lib/db/seed-data/genres.json, the reference genre table the app seeds (step 5.3a, D-096).
// Usage: node scripts/build-genre-seed.mjs
//
// Sources (all CC0):
//   - design/prototypes/pulse/genres-mb.js: the MusicBrainz genre list with a parent family and a Wikipedia article
//     count per genre, generated by design/prototypes/tools/build-genres.mjs on 2026-11-02 (D-062 (6)).
//   - The genres with their own Spirala traits (src/lib/music/genre-traits.ts) and four local genres (prototype
//     data.js `moreGenres`).
//
// Review of the D-062 mapping (plan 5.3): the prototype gave Folk to every genre that matched no rule. Here a genre
// whose parent is Folk keeps it only when an exception or a folk keyword (copied from build-genres.mjs below) says
// so; the rest get no family (a neutral colour). The prototype file does not record which Folk parents came from
// the Wikidata hierarchy, so those also become "no family": the safe direction (neutral rather than a wrong colour).
// MusicBrainz ids are not in the prototype file; they are filled by the catalogue sync once the live client runs
// (A4), matched on the English name.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const src = readFileSync(resolve(root, "design/prototypes/pulse/genres-mb.js"), "utf8");
const body = src.slice(src.indexOf("`") + 1, src.lastIndexOf("`"));
const mb = body
  .trim()
  .split("\n")
  .map((l) => {
    const [n, p, r] = l.split("|");
    return { n, p, r: Number(r) || 0 };
  });

// Genres with their own traits: [HR name (= trait key), EN name, family]. Families match genre-traits.ts.
const TRAITS = [
  ["Rock", "Rock", 1],
  ["Pop", "Pop", 2],
  ["K-pop", "K-pop", 2],
  ["Latino", "Latin", 5],
  ["Rap", "Hip hop", 3],
  ["Trap", "Trap", 3],
  ["Metal", "Metal", 0],
  ["Nu metal", "Nu metal", 0],
  ["Punk", "Punk", 0],
  ["Grunge", "Grunge", 0],
  ["Indie", "Indie", 1],
  ["Alternativa", "Alternative", 1],
  ["Elektronika", "Electronic", 4],
  ["Techno", "Techno", 4],
  ["House", "House", 4],
  ["Drum & bass", "Drum and bass", 4],
  ["R&B", "R&B", 3],
  ["Soul", "Soul", 5],
  ["Funk", "Funk", 5],
  ["Disco", "Disco", 2],
  ["Jazz", "Jazz", 5],
  ["Blues", "Blues", 5],
  ["Reggae", "Reggae", 6],
  ["Country", "Country", 6],
  ["Folk", "Folk", 6],
  ["Kantautorska", "Singer-songwriter", 6],
  ["Klasična", "Classical", 6],
  ["Filmska glazba", "Film music", 6],
];
// D-062 (4): the 20 main genres in order of popularity. They rank first in search.
const MAIN = [
  "Pop",
  "Rock",
  "Rap",
  "Elektronika",
  "Latino",
  "Klasična",
  "R&B",
  "Filmska glazba",
  "Country",
  "Reggae",
  "Metal",
  "Indie",
  "Jazz",
  "K-pop",
  "Soul",
  "Blues",
  "Folk",
  "Punk",
  "House",
  "Techno",
];
// Local genres (prototype data.js): [HR, EN, parent trait key, rank].
const LOCAL = [
  ["Zabavna", "Zabavna", "Pop", 20],
  ["Etno", "Etno", "Folk", 20],
  ["Tamburica", "Tamburica", "Folk", 20],
  ["Šansona", "Chanson", "Kantautorska", 20],
];

// From design/prototypes/tools/build-genres.mjs: the Folk exceptions and the folk keyword rule.
const FOLK_EXACT = new Set(["flamenco", "fado"]);
const FOLK_RE =
  /folk|acoustic|celtic|world|traditional|ethnic|klezmer|fado|polka|balkan|tamburica|rebetiko|qawwali|afro|highlife|jùjú|juju|mbalax|soukous|bhangra|raga|gamelan|throat|yodel|shanty|ballad|march|waltz|mazurka|tarantella|flamenco|sevillanas|morna|coladeira|griot|kora|desert|gnawa|raï|chaabi|dabke|mizrahi|arabesque|türkü|halk|manele|muzică|narodna|starogradska|néo|sertanejo|ghazal|qasida|maqam|bhajan|kirtan|lavani|baul|joik|kulning|polska|hambo|reel|jig|hornpipe|strathspey|pibroch|bagpipe|accordion|harp|zither|dulcimer|banjo|mandolin/;

const slugify = (s) =>
  s
    .toLowerCase()
    .replace(/đ/g, "d")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/&/g, " and ")
    .replace(/'/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

const out = [];
const bySlug = new Map();
const add = (row) => {
  if (!row.slug) throw new Error(`empty slug for ${row.nameEn}`);
  if (bySlug.has(row.slug))
    throw new Error(`slug collision: ${row.slug} (${row.nameEn} / ${bySlug.get(row.slug).nameEn})`);
  bySlug.set(row.slug, row);
  out.push(row);
};
const traitSlug = new Map(TRAITS.map(([hr, en]) => [hr, slugify(en)]));
const familyOf = new Map(TRAITS.map(([hr, , f]) => [hr, f]));

for (const [hr, en, f] of TRAITS) {
  const i = MAIN.indexOf(hr);
  add({
    slug: slugify(en),
    nameHr: hr,
    nameEn: en,
    family: f,
    parent: null,
    rank: i >= 0 ? 1100 - i : 1000,
  });
}
for (const [hr, en, p, r] of LOCAL) {
  add({
    slug: slugify(hr),
    nameHr: hr,
    nameEn: en,
    family: familyOf.get(p),
    parent: traitSlug.get(p),
    rank: r,
  });
}
const stats = { kept: 0, folkKept: 0, noFamily: 0, suffixed: 0 };
for (const { n, p, r } of mb) {
  const key = n.toLowerCase();
  let parent = p;
  if (p === "Folk" && !FOLK_EXACT.has(key) && !FOLK_RE.test(key)) parent = null;
  if (parent && !traitSlug.has(parent)) throw new Error(`unknown parent ${parent} for ${n}`);
  if (!parent) stats.noFamily++;
  else if (parent === "Folk") stats.folkKept++;
  else stats.kept++;
  // Two MusicBrainz genres can fold to one slug ("Kasékò" and "Kaseko"): the second gets a suffix.
  let slug = slugify(n);
  for (let k = 2; bySlug.has(slug); k++) {
    slug = `${slugify(n)}-${k}`;
    stats.suffixed++;
  }
  add({
    slug,
    nameHr: n,
    nameEn: n,
    family: parent ? familyOf.get(parent) : null,
    parent: parent ? traitSlug.get(parent) : null,
    rank: r,
  });
}

const file = resolve(root, "src/lib/db/seed-data/genres.json");
mkdirSync(dirname(file), { recursive: true });
const header = {
  generatedBy: "scripts/build-genre-seed.mjs",
  source:
    "MusicBrainz genre list (CC0) via design/prototypes/pulse/genres-mb.js; Wikidata sitelinks (CC0) as rank",
  columns: ["slug", "nameHr", "nameEn", "family", "parentSlug", "rank"],
};
writeFileSync(
  file,
  JSON.stringify({
    ...header,
    rows: out.map((g) => [g.slug, g.nameHr, g.nameEn, g.family, g.parent, g.rank]),
  }) + "\n",
);
console.log(`wrote ${out.length} genres to ${file}`, stats);
